$sourceDir = "gelen"
$targetBaseDir = "arsiv"

# Medya uzantıları (küçük/büyük harf duyarsız kontrol için regex ile kullanılacak)
$mediaExtensions = @(".jpg", ".jpeg", ".png", ".mp4", ".mov")

if (-not (Test-Path $sourceDir)) {
    Write-Error "Kaynak dizin '$sourceDir' bulunamadı."
    exit 1
}

# Tüm dosyaları al (alt klasörler dahil)
$files = Get-ChildItem -Path $sourceDir -File -Recurse

foreach ($file in $files) {
    $ext = $file.Extension.ToLower()

    # Sadece medya dosyası mı kontrol et
    if ($mediaExtensions -contains $ext) {
        $fileName = $file.Name
        $dateMatch = $null

        # 1. YYYYMMDD (20 ile başlayan 8 rakam) veya 2. YYYY-MM-DD kalıbı
        if ($fileName -match '(20\d{6})') {
            $dateStr = $Matches[1]
            try {
                $dateMatch = [DateTime]::ParseExact($dateStr, "yyyyMMdd", $null)
            } catch {}
        }
        elseif ($fileName -match '(20\d{4}-\d{2}-\d{2})') {
            $dateStr = $Matches[1]
            try {
                $dateMatch = [DateTime]::ParseExact($dateStr, "yyyy-MM-dd", $null)
            } catch {}
        }

        if ($dateMatch -and $dateMatch.Year -ge 2000) {
            # Tarih bulundu: arsiv/YYYY/MM/ altına taşı
            $year = $dateMatch.ToString("yyyy")
            $month = $dateMatch.ToString("MM")
            $destDir = Join-Path $targetBaseDir "$year\$month"
        } else {
            # Tarih bulunamadı: arsiv/tarihsiz/ altına taşı
            $destDir = Join-Path $targetBaseDir "tarihsiz"
        }

        if (-not (Test-Path $destDir)) {
            New-Item -Path $destDir -ItemType Directory -Force | Out-Null
        }

        # Dosyayı taşı (aynı isimde dosya varsa üzerine yazmamak için kontrol eklenebilir ama basitlik adına direkt taşıyoruz)
        $destPath = Join-Path $destDir $file.Name
        Move-Item -Path $file.FullName -Destination $destPath -Force
        Write-Host "Taşındı: $($file.Name) -> $destDir"
    } else {
        Write-Host "Atlandı (Medya değil): $($file.Name)"
    }
}

